   452  /* Parse the IP-literal construction from RFC 6874 (which extends RFC 3986 to
   453   * support IPv6 zone identifiers.
   454   *
   455   * Currently, IP versions beyond 6 (i.e. the IPvFuture rule) are unsupported.
   456   * There’s no point supporting them until (a) they exist and (b) the rest of the
   457   * stack (notably, sockets) supports them.
   458   *
   459   * Rules:
   460   *
   461   * IP-literal = "[" ( IPv6address / IPv6addrz / IPvFuture  ) "]"
   462   *
   463   * ZoneID = 1*( unreserved / pct-encoded )
   464   *
   465   * IPv6addrz = IPv6address "%25" ZoneID
   466   *
   467   * If %G_URI_FLAGS_PARSE_RELAXED is specified, this function also accepts:
   468   *
   469   * IPv6addrz = IPv6address "%" ZoneID
   470   */
   471  static gboolean
   472  parse_ip_literal (const gchar  *start,
   473                    gsize         length,
   474                    GUriFlags     flags,
   475                    gchar       **out,
   476                    GError      **error)
   477  {
   478    gchar *pct, *zone_id = NULL;
   479    gchar *addr = NULL;
   480    gsize addr_length = 0;
   481    gsize zone_id_length = 0;
   482    gchar *decoded_zone_id = NULL;
   483
   484    if (start[length - 1] != ']')
   485      goto bad_ipv6_literal;
   486
   487    /* Drop the square brackets */
   488    addr = g_strndup (start + 1, length - 2);
   489    addr_length = length - 2;
   490
   491    /* If there's an IPv6 scope ID, split out the zone. */
   492    pct = strchr (addr, '%');
   493    if (pct != NULL)
   494      {
   495        *pct = '\0';
   496
   497        if (addr_length - (pct - addr) >= 4 &&
   498            *(pct + 1) == '2' && *(pct + 2) == '5')
   499          {
   500            zone_id = pct + 3;
   501            zone_id_length = addr_length - (zone_id - addr);
   502          }
   503        else if (flags & G_URI_FLAGS_PARSE_RELAXED &&
   504                 addr_length - (pct - addr) >= 2)
   505          {
   506            zone_id = pct + 1;
   507            zone_id_length = addr_length - (zone_id - addr);
   508          }
   509        else
   510          goto bad_ipv6_literal;
   511
   512        g_assert (zone_id_length >= 1);
   513      }
   514
   515    /* addr must be an IPv6 address */
   516    if (!g_hostname_is_ip_address (addr) || !strchr (addr, ':'))
   517      goto bad_ipv6_literal;
   518
   519    /* Zone ID must be valid. It can contain %-encoded characters. */
   520    if (zone_id != NULL &&
   521        !uri_decode (&decoded_zone_id, NULL, zone_id, zone_id_length, FALSE,
   522                     flags, G_URI_ERROR_BAD_HOST, NULL))
   523      goto bad_ipv6_literal;
   524
   525    /* Success */
   526    if (out != NULL && decoded_zone_id != NULL)
   527      *out = g_strconcat (addr, "%", decoded_zone_id, NULL);
   528    else if (out != NULL)
   529      *out = g_steal_pointer (&addr);
   530
   531    g_free (addr);
   532    g_free (decoded_zone_id);
   533
   534    return TRUE;
   535
   536  bad_ipv6_literal:
   537    g_free (addr);
   538    g_free (decoded_zone_id);
   539    g_set_error (error, G_URI_ERROR, G_URI_ERROR_BAD_HOST,
   540                 _("Invalid IPv6 address ‘%.*s’ in URI"),
   541                 (gint)length, start);
   542
   543    return FALSE;
   544  }
